.tile{border:1px solid var(--line);border-radius:12px;padding:12px 14px}
.tile .n{font:700 26px 'JetBrains Mono',monospace}.tile .n.g{color:var(--gold)}
.tile .l{font-size:13px;color:var(--muted);line-height:1.35}
.bar{display:flex;height:14px;border-radius:7px;overflow:hidden;margin:10px 0 8px;background:#333}
.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:13px;color:var(--muted)}
.legend span::before{content:"";display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px;background:var(--c)}
.tw{overflow-x:auto;border:1px solid var(--line);border-radius:12px}
