// Reconstruct lineups for chapters without a stored roster, in two passes.
// Pass 1: imported members still on the team + people later removed or moved off the team
//   who checked in at that event.
// Pass 2: current members who joined AFTER the import, checked in at that event, and are on
//   no other team's pass-1 lineup. Catches people removed before event logging started and
//   re-added later (Harissa's Ghassen Zaara: checked in at M1, re-added 2026-08-07).
const base = {};
for (const r of d.regs) {
  if (r.roster && r.roster.length) continue;
  const checked = new Set(d.checkedInApps[r.chapter_id] || []);
  const imported = d.members
    .filter((m) => m.team_id === r.team_id && m.joined_at.startsWith(MAKEATHON_IMPORT_DATE))
    .map((m) => m.user_id);
  const gone = [
    ...d.events.filter((e) => e.action === "team.member_removed" && e.entity_id === r.team_id)
      .map((e) => e.delta?.deleted?.user_id),
    ...d.events.filter((e) => e.action === "team.member_moved" && e.delta?.moved?.from_team === r.team_id)
      .map((e) => e.delta?.moved?.user_id),
  ].filter((u) => u && checked.has(email[u]));
  base[`${r.chapter_id}:${r.team_id}`] = new Set([...imported, ...gone]);
}
const onAnyBase = {};
for (const [key, set] of Object.entries(base)) {
  const cid = key.split(":")[0];
  set.forEach((u) => (onAnyBase[cid] ??= new Set()).add(u));
}
function rosterFor(r) {
  if (r.roster && r.roster.length) return { roster: [...r.roster].sort(), recon: false };
  const checked = new Set(d.checkedInApps[r.chapter_id] || []);
  const set = new Set(base[`${r.chapter_id}:${r.team_id}`]);
  d.members
    .filter((m) => m.team_id === r.team_id && checked.has(email[m.user_id]) && !onAnyBase[r.chapter_id]?.has(m.user_id))
    .forEach((m) => set.add(m.user_id));
  return { roster: [...set].sort(), recon: true };
}

