75	// state change here would be made by a robot on the applicant's behalf. The
76	// answer is written only by submitRsvp(), behind a deliberate click.
77	// tests/rsvp-no-write-on-get.test.ts pins this.
78	//
79	// As in getShowcaseByToken(), a real DB error THROWS (into the error boundary)
80	// instead of collapsing to null: a Supabase outage must not make every emailed
81	// RSVP link look permanently dead.
82	export async function getRsvpByToken(token: string): Promise<ResolvedRsvp | null> {
83	  if (!token || !isUuid(token)) return null;
84	
85	  const rl = await checkRateLimit(rsvpLimiter, await clientIp(), "rsvp");
86	  if (rl.limited) return null;
87	
88	  const adminClient = createAdminClient();
89	
90	  const { data: row, error } = await adminClient
91	    .from("application_rsvps")
92	    .select(
93	      "application_id, response, responded_at, email_sent_at, applications!inner(first_name, chapters!inner(name, city, country, date, date_end))"
94	    )
95	    .eq("rsvp_token", token)
96	    .maybeSingle();
97	
98	  if (error) throw error;
99	  if (!row?.application_id) return null;
100	
101	  // PostgREST types an embedded to-one join as an array in some client
102	  // versions, so normalise before reading.
103	  const application = (Array.isArray(row.applications) ? row.applications[0] : row.applications) as
104	    | Record<string, unknown>
105	    | undefined;
106	  if (!application) return null;
107	
108	  const chapter = (Array.isArray(application.chapters) ? application.chapters[0] : application.chapters) as
109	    | Record<string, unknown>
110	    | undefined;
111	  if (!chapter) return null;
112	
113	  const response = row.response as string | null;
114	
115	  return {
116	    applicationId: row.application_id as string,
117	    firstName: application.first_name as string,
118	    chapterName: chapter.name as string,
119	    chapterCity: `${chapter.city}, ${chapter.country}`,
120	    chapterDate: formatDateRange(chapter.date as string, chapter.date_end as string | null),
121	    response: isRsvpResponse(response) ? response : null,
122	    respondedAt: (row.responded_at as string) ?? null,
123	    // An expired link is NOT a 404. Unlike the showcase token (which guards
124	    // other people's personal data, so its expiry collapses into a uniform
125	    // null), this token guards a one-bit self-report by the one person it was
126	    // mailed to. Telling that person "the window closed" is worth far more than
127	    // hiding that their own link was once valid, and a 404 would read as a
128	    // broken link and generate support mail.
129	    expired: isRsvpExpired(row.email_sent_at as string),
130	    deadline: formatRsvpDeadline(row.email_sent_at as string),
131	  };
132	}
