134	// ─── Record an answer (public, POST only) ────────────────────
135	//
136	// The first answer is FINAL. The lock is enforced by the database, not by a
137	// read-then-write gap: the update carries `.is("response", null)`, so two
138	// concurrent submits (a double click, or a click racing a retry) can only ever
139	// produce one stored answer. A submit against an already-answered token is not
140	// an error, it just reports the answer that stands.
141	export async function submitRsvp(
142	  token: string,
143	  response: RsvpResponse
144	): Promise<
145	  | { error: string }
146	  | { success: true; response: RsvpResponse; alreadyAnswered: boolean }
147	> {
148	  if (!token || !isUuid(token)) return { error: "Invalid RSVP link." };
149	  if (!isRsvpResponse(response)) return { error: "Invalid response." };
150	
151	  const ipRl = await checkRateLimit(rsvpLimiter, await clientIp(), "rsvp");
152	  if (ipRl.limited) return { error: ipRl.error! };
153	  const tokenRl = await checkRateLimit(rsvpTokenLimiter, token, "rsvp-token");
154	  if (tokenRl.limited) return { error: tokenRl.error! };
155	
156	  const adminClient = createAdminClient();
157	
158	  // The window is enforced by the SAME statement that records the answer
159	  // (email_sent_at must still be inside it), so a submit landing a millisecond
160	  // after the deadline cannot slip through a read-then-write gap.
161	  const { data: updated, error } = await adminClient
162	    .from("application_rsvps")
163	    .update({ response, responded_at: new Date().toISOString() })
164	    .eq("rsvp_token", token)
165	    .is("response", null)
166	    .gt("email_sent_at", rsvpCutoffIso())
167	    .select("application_id, response")
168	    .maybeSingle();
169	
170	  if (error) return { error: "Could not record your answer. Please try again." };
171	
172	  if (updated?.application_id) {
173	    // Unauthenticated actor: the token bearer is not a logged-in account, so
174	    // this is a "system" event carrying the application it belongs to.
175	    logEvent({
176	      action: "application.rsvp_responded",
177	      entityType: "application",
178	      entityId: updated.application_id as string,
179	      actorType: "system",
180	      delta: { rsvp: { from: null, to: response } },
181	    });
182	    return { success: true, response, alreadyAnswered: false };
183	  }
184	
185	  // No row updated: the token is unknown, already answered, or expired.
186	  // Distinguish with a read so an already-answered applicant sees their answer
187	  // and an expired one is told why, while an unknown token stays a uniform
188	  // failure.
189	  const { data: existing } = await adminClient
190	    .from("application_rsvps")
191	    .select("response, email_sent_at")
192	    .eq("rsvp_token", token)
193	    .maybeSingle();
194	
195	  const standing = existing?.response as string | null | undefined;
196	  if (isRsvpResponse(standing)) {
197	    return { success: true, response: standing, alreadyAnswered: true };
198	  }
199	
200	  if (existing && isRsvpExpired(existing.email_sent_at as string)) {
201	    return {
202	      error:
203	        "This RSVP link has expired. Please contact the organisers if you still want your spot.",
204	    };
205	  }
206	
207	  return { error: "Invalid RSVP link." };
208	}
209	
210	// ─── Admin: send the RSVP request to all accepted applicants ─
211	//
212	// Idempotent by construction: an application_rsvps row exists only once someone
213	// has been asked, so this mails exactly the accepted applicants who have no row
214	// yet. Pressing the button twice mails nobody twice; newly accepted people are
215	// picked up on the next press.
216	//
217	// ONE press mails everybody. There is no fixed chunk (sendBulkEmails() uses 40
218	// and makes the admin click three times for 85 applicants). Instead this
219	// borrows the two mechanisms the codebase already trusts elsewhere:
220	//
221	//   - concurrency, like sendCertificateEmails(): a job per recipient, each
222	//     catching its own error, run SEND_CONCURRENCY-wide. lib/email.ts opens a
223	//     pool with maxConnections: 3, which a sequential await loop never uses, so
224	//     matching that number here is roughly a threefold speedup for free;
225	//   - a wall-clock budget, like sendChapterBroadcast(): stop with time to spare
226	//     before the function timeout and report what is left, rather than dying
227	//     mid-send with no record of how far it got.
228	//
229	// So a realistic chapter goes out in one press, and a pathologically large one
230	// still degrades safely into an accurate `remaining` instead of a timeout. The
231	// scheduling itself lives in lib/bulk-send.ts, shared with the acceptance and
232	// rejection sends.
233	
234	export async function sendRsvpEmails(chapterId: string): Promise<
235	  | { error: string }
236	  | { success: true; sent: number; remaining: number; failed: string[] }
237	> {
238	  const authErr = await requireChapterAdminAction(chapterId);
239	  if (authErr) return { error: authErr };
240	
241	  const adminClient = createAdminClient();
242	
243	  const { data: accepted, error } = await adminClient
244	    .from("applications")
245	    .select(
246	      "id, email, first_name, chapters!inner(name, city, country, date, date_end), application_rsvps(application_id)"
247	    )
248	    .eq("chapter_id", chapterId)
249	    .eq("status", "accepted")
250	    .limit(QUERY_LIMITS.applicationsPerChapter);
251	
252	  if (error) return { error: "Could not load accepted applications." };
253	
254	  const pending = (accepted ?? []).filter((a) => {
255	    const rsvp = a.application_rsvps;
256	    return Array.isArray(rsvp) ? rsvp.length === 0 : !rsvp;
257	  });
258	
259	  if (pending.length === 0) {
260	    return { success: true, sent: 0, remaining: 0, failed: [] };
261	  }
262	
263	  let sent = 0;
264	  const failed: string[] = [];
265	
266	  // The budget is enforced before the insert below: a recipient it did not
267	  // reach must leave no row behind, or the next press would consider them
268	  // already asked and they would never be mailed.
269	  const { skipped } = await runBudgetedConcurrent(pending, async (app) => {
270	    const chapter = (Array.isArray(app.chapters) ? app.chapters[0] : app.chapters) as Record<
271	      string,
272	      unknown
273	    >;
274	
275	    // Insert first so the token comes from the column default, then mail it.
276	    const { data: inserted, error: insertErr } = await adminClient
277	      .from("application_rsvps")
278	      .insert({ application_id: app.id })
279	      .select("rsvp_token")
280	      .single();
281	
282	    if (insertErr || !inserted?.rsvp_token) {
283	      failed.push(app.email as string);
284	      return;
285	    }
286	
287	    try {
288	      const html = await renderRsvpRequestEmail({
289	        firstName: app.first_name as string,
290	        chapterName: chapter.name as string,
291	        chapterCity: `${chapter.city}, ${chapter.country}`,
292	        chapterDate: formatDateRange(chapter.date as string, chapter.date_end as string | null),
293	        rsvpToken: inserted.rsvp_token as string,
294	        deadline: formatRsvpDeadline(new Date()),
295	      });
296	
297	      await sendEmail({
298	        to: app.email as string,
299	        subject: `One click left: secure your spot at ${chapter.name}`,
300	        html,
301	        skipRateLimit: true,
302	      });
303	      sent++;
304	    } catch (err) {
305	      console.error(`Failed to send RSVP email to ${app.email}:`, err);
306	      // Roll the row back so this applicant is picked up again on the next
307	      // press instead of being silently marked as asked.
308	      await adminClient.from("application_rsvps").delete().eq("application_id", app.id);
309	      failed.push(app.email as string);
310	    }
311	  });
312	
313	  if (sent > 0) {
314	    logEvent({
315	      action: "application.rsvp_requested",
316	      entityType: "chapter",
317	      entityId: chapterId,
318	      actorId: await getActingUserId(),
319	      actorType: "admin",
320	      delta: { rsvp_emails: { sent, failed: failed.length, skipped: skipped.length } },
321	    });
322	  }
323	
324	  return { success: true, sent, remaining: skipped.length, failed };
325	}
