332	export async function rotateWalkInToken(
333	  chapterId: string
334	): Promise<{ error: string } | { token: string }> {
335	  const authErr = await requireChapterAdminAction(chapterId);
336	  if (authErr) return { error: authErr };
337	
338	  const session = await getSession();
339	  const actorId = session?.profile?.id ?? null;
340	
341	  const adminClient = createAdminClient();
342	
343	  const newToken = crypto.randomUUID();
344	  const { data, error } = await adminClient
345	    .from("chapter_walk_in")
346	    .upsert(
347	      {
348	        chapter_id: chapterId,
349	        walk_in_token: newToken,
350	        rotated_at: new Date().toISOString(),
351	        rotated_by: actorId,
352	      },
353	      { onConflict: "chapter_id" }
354	    )
355	    .select("walk_in_token")
356	    .single();
357	
358	  if (error || !data) {
359	    return { error: error?.message || "Failed to rotate token." };
360	  }
361	
362	  logEvent({
363	    action: "chapter.walk_in_token_rotated",
364	    entityType: "chapter",
365	    entityId: chapterId,
366	    actorId,
367	    actorType: "admin",
368	    delta: { rotated: { chapter_id: chapterId } },
369	  });
370	
371	  return { token: data.walk_in_token as string };
372	}
