380	  chapterId: string
381	): Promise<{ error: string } | { token: string }> {
382	  const authErr = await requireChapterAdminAction(chapterId);
383	  if (authErr) return { error: authErr };
384	
385	  const adminClient = createAdminClient();
386	
387	  const { data: existing } = await adminClient
388	    .from("chapter_walk_in")
389	    .select("walk_in_token")
390	    .eq("chapter_id", chapterId)
391	    .maybeSingle();
392	
393	  if (existing?.walk_in_token) {
394	    return { token: existing.walk_in_token as string };
395	  }
396	
397	  const { data: created, error } = await adminClient
398	    .from("chapter_walk_in")
399	    .insert({ chapter_id: chapterId })
